import{_ as s,C as n,o as i,c as r,j as t,a as o,E as h,ak as c}from"./chunks/framework.sV-XtlWr.js";const l="/diagrams/uncovered-changes.svg",d="/screenshots/uncovered-changes.png",w=JSON.parse('{"title":"Uncovered changes in pull requests","description":"The files a pull request changed that no test observably reaches, posted on the pull request as a comment section and a commit status, with a warn-only gate flag.","frontmatter":{"title":"Uncovered changes in pull requests","description":"The files a pull request changed that no test observably reaches, posted on the pull request as a comment section and a commit status, with a warn-only gate flag.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/uncovered-changes.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/uncovered-changes.html"}],["meta",{"property":"og:title","content":"Uncovered changes in pull requests | Piwi Dashboard"}],["meta",{"property":"og:description","content":"The files a pull request changed that no test observably reaches, posted on the pull request as a comment section and a commit status, with a warn-only gate flag."}]]},"headers":[],"relativePath":"features/uncovered-changes.md","filePath":"features/uncovered-changes.md","lastUpdated":1792608897000}'),p={name:"features/uncovered-changes.md"};function g(u,e,m,f,k,v){const a=n("Needs");return i(),r("div",null,[e[0]||(e[0]=t("h1",{id:"uncovered-changes-in-pull-requests",tabindex:"-1"},[o("Uncovered changes in pull requests "),t("a",{class:"header-anchor",href:"#uncovered-changes-in-pull-requests","aria-label":'Permalink to "Uncovered changes in pull requests"'},"​")],-1)),h(a,{reporter:"",scm:""}),e[1]||(e[1]=c('<p>A pull request that changes <code>server/api/orders/[id].patch.ts</code> while no test ever requests that route passes CI and proves nothing about the change. When a run finishes, Piwi joins the files its change touched to the tests that <a href="/guide/concepts.html#reach">observably reach</a> them, and names the changed files nothing reaches. Each one is a <em>changed, unreached</em> <a href="/features/scenario-gaps.html">scenario gap</a>, with a draft scenario to start from.</p><figure><img src="'+l+'" alt="A pull-request run&#39;s changed files are joined to the tests that reach them; each is reached, a changed-unreached gap, or without evidence; the gaps go to the pull request"></figure><h2 id="what-counts-as-reached" tabindex="-1">What counts as reached <a class="header-anchor" href="#what-counts-as-reached" aria-label="Permalink to &quot;What counts as reached&quot;">​</a></h2><p>A changed file counts as reached when a test that ran recently touches it:</p><ul><li>a route or page the file serves, matched by the framework&#39;s file naming (<code>server/api/**</code>, <code>server/routes/**</code>, Nuxt <code>pages/**</code>), that a test requested or visited;</li><li>a test step whose locator is written in the file (a page object, a helper), or the file is the spec that defines the test.</li><li>with <a href="/features/code-reach.html">code reach</a> on, a test executed one of the file&#39;s functions;</li><li>with <a href="/features/combined-coverage.html">combined coverage</a> uploaded for the head commit, a suite (a unit suite or the Playwright suite) ran one of the lines the change added or modified.</li></ul><p>&quot;No test in this run&quot; is always paired with the count from the last 30 runs, so a run narrowed by a <a href="/features/test-selection.html">selection</a> is never mistaken for a gap. A skipped test reaches nothing. A file that no route, page or test source maps to says so: no evidence either way.</p><p>The diff comes from the <a href="/guide/source-control.html">source control</a> connection: a pull-request run is compared with its base branch, any other run with the commit of the last passing run. With no SCM token or no diff, nothing appears.</p><h2 id="on-the-pull-request" tabindex="-1">On the pull request <a class="header-anchor" href="#on-the-pull-request" aria-label="Permalink to &quot;On the pull request&quot;">​</a></h2><p>With <a href="/features/pr-feedback.html">pull-request feedback</a> turned on, the comment gains an <strong>Uncovered changes</strong> section, grouped by ticket (read from the commit messages and the pull request):</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">#### 🟣 Uncovered changes · 3 of 7 files · 2 tickets</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Observed reach, not instrumented coverage. This run and the last 30 on </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`main`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**PROJ-418**</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> `server/api/orders/[id].patch.ts`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> · changed (+41 −3) · 0 tests in 30 runs</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  → </span><span style="--shiki-light:#24292E;--shiki-light-font-style:italic;--shiki-dark:#E1E4E8;--shiki-dark-font-style:italic;">*a scenario that exercises [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">id</span><span style="--shiki-light:#24292E;--shiki-light-font-style:italic;--shiki-dark:#E1E4E8;--shiki-dark-font-style:italic;">].patch.ts*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> · draft</span></span></code></pre></div><p>When the head commit has <a href="/features/combined-coverage.html">combined coverage</a>, the section opens with the change&#39;s patch coverage, counted on the lines that can run:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Patch coverage 82.9%**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 34 of the 41 changed lines ran (unit 28, end to end 19), at </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`a1b2c3d`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span></code></pre></div><figure><img src="'+d+'" alt="The Uncovered changes section of a pull-request comment"><figcaption>Patch coverage, then the changed files no test reaches.</figcaption></figure><p>A coverage report uploaded for the commit after the comment, or the run&#39;s own coverage arriving after it, posts the comment again a few seconds later; a later push&#39;s comment is never overwritten by an earlier commit&#39;s.</p><p>When commit statuses are on too, a second status joins the run&#39;s own: <code>piwi/tests/change-coverage</code> with the default status context, described as <em>3 of 7 changed files have no observed reach</em>, with the patch coverage when there is one. It is always <strong>success</strong>, so it informs a reviewer without blocking the merge. The section and the status are left out while the <em>changed, unreached</em> detector is <a href="/features/scenario-gaps.html#triage">muted</a> on the project, or where the Test Map is declined.</p><h2 id="from-an-agent" tabindex="-1">From an agent <a class="header-anchor" href="#from-an-agent" aria-label="Permalink to &quot;From an agent&quot;">​</a></h2><p>The <a href="/reference/mcp-tools.html#get_change_coverage"><code>get_change_coverage</code></a> MCP tool returns the same join for a run or for an explicit base and head commit, grouped by ticket, without recording anything. The <a href="/features/agent-skills.html">write-the-missing-test</a> skill takes it from there. The REST endpoint is in the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a>.</p><h2 id="the-gate-flag" tabindex="-1">The gate flag <a class="header-anchor" href="#the-gate-flag" aria-label="Permalink to &quot;The gate flag&quot;">​</a></h2><p><code>piwi gate --max-uncovered-changes &lt;n&gt;</code> adds a warning to the <a href="/guide/ci.html#blocking-a-merge">gate</a> result when more than <code>n</code> changed files have no observed reach. It is <strong>warn-only</strong>: it never changes the verdict or the exit code, because observed reach is evidence, not proof. Without the flag, the gate ignores uncovered changes.</p><p><code>piwi gate --min-patch-coverage &lt;percent&gt;</code> warns, the same way, when fewer of the changed lines ran, or when the head commit&#39;s coverage names none of them. Run it after the unit-test jobs uploaded their reports.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Observed reach, not coverage.</strong> A reached file may still hide an untested branch; an unreached one may be dead code.</li><li><strong>Naming conventions.</strong> Files map to routes and pages through Nitro and Nuxt file naming; other frameworks rely on locators and spec files, so more of their files show as <em>no evidence</em>.</li><li><strong>Ten files listed.</strong> The comment names at most ten uncovered files and counts the rest.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/scenario-gaps.html">Scenario gaps &amp; the Test Map</a>: the other gaps, and triage</li><li><a href="/features/pr-feedback.html">Pull-request feedback &amp; re-run</a>: the comment this section joins</li><li><a href="/guide/source-control.html">Source control</a>: the token that provides the diff</li><li><a href="/reference/cli.html#gate">Piwi CLI: gate</a>: every gate flag</li></ul>',24))])}const y=s(p,[["render",g]]);export{w as __pageData,y as default};
